(()=>{'use strict';const root=document.getElementById('designer-next-step');if(!root)return;let last='';function read(key){try{return JSON.parse(localStorage.getItem(key))||{};}catch{return {};}}function render(){const base=read('zuxuru-fashion-service-v1'),work=read('zuxuru-designer-work-v1');const products=Array.isArray(base.products)?base.products:[],projects=Array.isArray(work.studio)?work.studio:[],orders=Array.isArray(base.orders)?base.orders:[];const profile=!!String(base.designer?.name||'').trim();const steps=[{title:'Save your designer profile',href:'#designer',done:profile,note:'Tell your story and add your business contact details.'},{title:'Add your first collection design',href:'#catalogue',done:products.length>0,note:'Record sizes, colours, availability and confirmed costs.'},{title:'Record a creative project',href:'#my-studio',done:projects.length>0,note:'Save your creative brief, then open Digital Studio to produce it.'},{title:'Record your first customer enquiry',href:'#orders',done:orders.length>0,note:'Record an actual enquiry and agree the next action with the customer.'}];const due=o=>{const value=String(o.due||'');return /^\d{4}-\d{2}-\d{2}$/.test(value)&&Number.isFinite(Date.parse(value+'T12:00:00Z'))?value:'9999-99-99';};const open=orders.filter(o=>o&& !['Delivered','Closed'].includes(o.stage)).sort((a,b)=>due(a).localeCompare(due(b)))[0];const costs=['materials','labour','production','packCost','delivery','other'];const uncosted=products.find(p=>!costs.every(k=>Number.isFinite(p[k])&&p[k]>=0)||!Number.isFinite(p.price)||p.price<=0);const costing=uncosted?{title:'Confirm your garment costs',href:'#catalogue',note:'Review '+String(uncosted.name||'your design')+': materials, labour, production, packaging, delivery, other costs and selling price. Record zero only when confirmed.'}:null;const next=open?{title:'Move your customer enquiry forward',href:'#orders',note:'Review the recorded stage and next action for '+String(open.customer||'your customer')+(due(open)!=='9999-99-99'?' Target date: '+due(open)+'.':'.')}:costing||steps.find(s=>!s.done)||{title:'Review your daily work',href:'#my-work',note:'Your starting records are in place. Review tasks and choose your next business action.'};const signature=JSON.stringify({steps,next});if(signature===last)return;last=signature;document.getElementById('next-step-title').textContent=next.title;document.getElementById('next-step-message').textContent=next.note;const action=document.getElementById('next-step-action');action.href=next.href;action.onclick=open?event=>{event.preventDefault();document.dispatchEvent(new CustomEvent('fashion-open-order',{detail:{id:open.id}}));}:null;action.textContent=open?'Open sales & delivery →':'Continue →';const list=document.getElementById('next-step-checklist');list.replaceChildren();for(const step of steps){const item=document.createElement('li'),link=document.createElement('a');link.href=step.href;link.textContent=step.title;item.append(link,document.createTextNode(step.done?' · Record saved':' · To start'));list.append(item);}}render();document.addEventListener('submit',()=>setTimeout(render,0));for(const name of ['fashion-storefront-updated','fashion-enquiry-import','studio-workspace-updated'])window.addEventListener(name,()=>setTimeout(render,0));document.addEventListener('visibilitychange',()=>{if(!document.hidden)render();});setInterval(()=>{if(!document.hidden)render();},5000);})();
